Contract CoCoMEOrderProducts::orderItem(barcode:Integer,quantity:Integer): Boolean {
          definition:
          item:Item = Item.allInstance()->any(i | i.Barcode = barcode)


            postcondition:
          if item.oclIsUndefined() then let entry:OrderEntry in entry.oclIsNew() and entry.Quantity = quantity and entry.SubAmount = 0 and entry.Item = null and self.CurrentOrderProduct.ContainedEntries->includes(entry) and result = false else let entry:OrderEntry in entry.oclIsNew() and entry.Quantity = quantity and entry.SubAmount = item.Price * quantity and entry.Item = item and self.CurrentOrderProduct.ContainedEntries->includes(entry) and result = true endif

        }
